# Phare agent installer (Linux). Generated by your Phare hub.
set -eu

HUB={!! $hub !!}
TOKEN={!! $token !!}
AGENT_URL_PREFIX={!! $agentDownloadPrefix !!}

say() { printf '%s\n' "$*"; }
fail() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }

say "Phare - installing the monitoring agent..."

[ "$(uname -s)" = "Linux" ] || fail "This installer only supports Linux servers."
[ "$(id -u)" = "0" ] || fail "Please run it as administrator: add 'sudo' before 'sh'."

case "$(uname -m)" in
    x86_64|amd64) ARCH=amd64 ;;
    aarch64|arm64) ARCH=arm64 ;;
    *) fail "Unsupported processor: $(uname -m)." ;;
esac

BIN=/usr/local/bin/phare-agent
TMP="$(mktemp)"
AGENT_URL="${AGENT_URL_PREFIX}${ARCH}"

say "1/3 Downloading the agent..."
if command -v curl >/dev/null 2>&1; then
    curl -fsSL "$AGENT_URL" -o "$TMP" || fail "Download failed. The official Phare release {{ $agentReleaseTag }} must be published on GitHub (this server needs outbound HTTPS)."
elif command -v wget >/dev/null 2>&1; then
    wget -q "$AGENT_URL" -O "$TMP" || fail "Download failed. The official Phare release {{ $agentReleaseTag }} must be published on GitHub (this server needs outbound HTTPS)."
else
    fail "Neither curl nor wget is installed."
fi
chmod 755 "$TMP"
mv "$TMP" "$BIN"

say "2/3 Connecting this server to Phare..."
"$BIN" enroll --hub "$HUB" --token "$TOKEN" || fail "Could not connect to Phare. The link may have expired: generate a new command."

say "3/3 Starting the agent..."
if command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ]; then
    cat > /etc/systemd/system/phare-agent.service <<'UNIT'
[Unit]
Description=Phare monitoring agent
After=network-online.target
Wants=network-online.target

[Service]
ExecStart=/usr/local/bin/phare-agent -config /etc/phare-agent/config.yaml
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
UNIT
    systemctl daemon-reload
    if systemctl is-active phare-agent >/dev/null 2>&1; then
        systemctl restart phare-agent
    else
        systemctl enable --now phare-agent >/dev/null 2>&1
    fi
    say "Done! This server will appear in Phare within a minute."
else
    say "Connected, but this server has no systemd. Start the agent with:"
    say "  $BIN -config /etc/phare-agent/config.yaml"
fi